/* Local-only measured RSSI export. Icons are embedded in the KMZ, no remote requests. */
(()=>{'use strict';
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function icon(color){const c=document.createElement('canvas');c.width=c.height=32;const x=c.getContext('2d');x.beginPath();x.arc(16,16,13,0,Math.PI*2);x.fillStyle='#fff';x.fill();x.lineWidth=3;x.strokeStyle='#111827';x.stroke();x.beginPath();x.arc(16,16,9,0,Math.PI*2);x.fillStyle=color;x.fill();return Uint8Array.from(atob(c.toDataURL('image/png').split(',')[1]),v=>v.charCodeAt(0))}
function build(points,visible=true,makeIcon=icon){if(!points.length)return {kml:'',files:[]};const styles=new Map(),files=[],parts=['<Folder><name>ผลวัดจริง RSSI ลูกข่าย</name><visibility>'+Number(visible)+'</visibility><description>รวมทุกจุดที่นำเข้า ไม่จำกัดรัศมีหรือพิกัดแม่ข่าย สีตามระดับ RSSI ของ Sim; ต่ำกว่า -105 dBm เป็นสีเทา</description>'];
for(const p of points){const color=RFFieldMap.color(p.rssi);if(!styles.has(color)){const id='field-rssi-'+styles.size,path='field-icons/'+id+'.png';styles.set(color,id);files.push([path,makeIcon(color)]);parts.push('<Style id="'+id+'"><IconStyle><color>ffffffff</color><scale>1</scale><Icon><href>'+path+'</href></Icon><hotSpot x="0.5" y="0.5" xunits="fraction" yunits="fraction"/></IconStyle><LabelStyle><scale>0</scale></LabelStyle></Style>')}const data={RSSI_dBm:p.rssi,latitude:p.lat,longitude:p.lon,station:p.name,base_station:p.base||'',source_row:p.row};parts.push('<Placemark><name>'+escape(p.name)+'</name><description>'+escape('RSSI วัดจริง: '+p.rssi+' dBm\nพิกัด: '+p.lat+', '+p.lon+(p.base?'\nแม่ข่ายที่ระบุในไฟล์: '+p.base:'')+'\nแถวต้นฉบับ: '+p.row)+'</description><styleUrl>#'+styles.get(color)+'</styleUrl><ExtendedData>'+Object.entries(data).map(([k,v])=>'<Data name="'+k+'"><value>'+escape(v)+'</value></Data>').join('')+'</ExtendedData><Point><altitudeMode>clampToGround</altitudeMode><coordinates>'+p.lon+','+p.lat+',0</coordinates></Point></Placemark>')}
parts.push('</Folder>');return {kml:parts.join(''),files}}
globalThis.RFFieldKMZ={build};
})();
